SELECT AC.ID, AC.CREATE_TIME, AC.MODIFY_TIME, AC.LOGIC_DEL, AC.REC_VER, AC.TENANT_ID, AC.COST_DESC, AC.OUTLAY, AC.COST_TYPE, AC.PAYMENT_SIGN, AC.PAYMENT_TIME, AC.ICON, AC.REMARK, AC.USER_ID, (SELECT NICK_NAME FROM SYS_USER WHERE ID = AC.USER_ID) AS AC_NICK_NAME, GROUP_CONCAT(SU.ID) AS SU_ID, GROUP_CONCAT(SU.NICK_NAME) AS NICK_NAME FROM account_cost AC LEFT JOIN account_cost_user ACU ON AC.ID = ACU.COST_ID LEFT JOIN sys_user SU ON ACU.USER_ID = SU.ID WHERE 1 = 1 AND AC.LOGIC_DEL = 0 AND AC.USER_ID = #{accountCost.userId} AND AC.TENANT_ID = #{accountCost.tenantId}
AND AC.COST_DESC like CONCAT('%', #{accountCost.costDesc}, '%')
AND AC.REMARK LIKE ('%', #{accountCost.remark}, '%')
AND AC.PAYMENT_SIGN = #{accountCost.paymentSign}
AND AC.PAYMENT_TIME >= #{accountCost.paymentTimeFrom} AND AC.PAYMENT_TIME <= #{accountCost.paymentTimeTo}
AND AC.COST_TYPE IN
#{item}
AND ACU.USER_ID IN
#{item}
GROUP BY AC.ID
UNION ALL
SELECT AC.ID, AC.CREATE_TIME, AC.MODIFY_TIME, AC.LOGIC_DEL, AC.REC_VER, AC.TENANT_ID, AC.COST_DESC, AC.OUTLAY, AC.COST_TYPE, AC.PAYMENT_SIGN, AC.PAYMENT_TIME, AC.ICON, AC.REMARK, AC.USER_ID, (SELECT NICK_NAME FROM SYS_USER WHERE ID = AC.USER_ID) AS AC_NICK_NAME, GROUP_CONCAT(SU.ID) AS SU_ID, GROUP_CONCAT(SU.NICK_NAME) AS NICK_NAME FROM account_cost AC LEFT JOIN account_cost_user ACU ON AC.ID = ACU.COST_ID INNER JOIN sys_user SU ON ACU.USER_ID = SU.ID WHERE 1 = 1 AND AC.LOGIC_DEL = 0 AND AC.TENANT_ID = #{accountCost.tenantId} AND AC.USER_ID <> #{accountCost.userId}
AND AC.COST_DESC like CONCAT('%', #{accountCost.costDesc}, '%')
AND AC.REMARK LIKE ('%', #{accountCost.remark}, '%')
AND AC.PAYMENT_SIGN = #{accountCost.paymentSign}
AND AC.PAYMENT_SIGN = #{accountCost.paymentSign}
AND AC.PAYMENT_TIME >= #{accountCost.paymentTimeFrom} AND AC.PAYMENT_TIME <= #{accountCost.paymentTimeTo}
AND AC.COST_TYPE IN
#{item}
AND ACU.USER_ID IN
#{item}
GROUP BY AC.ID ORDER BY PAYMENT_TIME DESC, MODIFY_TIME DESC

SELECT AC.ID, AC.CREATE_TIME, AC.MODIFY_TIME, AC.LOGIC_DEL, AC.REC_VER, AC.TENANT_ID, AC.COST_DESC, AC.OUTLAY, AC.COST_TYPE, AC.PAYMENT_SIGN, AC.PAYMENT_TIME, AC.ICON, AC.REMARK, AC.USER_ID, (SELECT NICK_NAME FROM SYS_USER WHERE ID = AC.USER_ID) AS AC_NICK_NAME, GROUP_CONCAT(SU.ID) AS SU_ID, GROUP_CONCAT(SU.NICK_NAME) AS NICK_NAME FROM account_cost AC LEFT JOIN account_cost_user ACU ON AC.ID = ACU.COST_ID LEFT JOIN sys_user SU ON ACU.USER_ID = SU.ID WHERE 1 = 1 AND AC.LOGIC_DEL = 0 AND AC.USER_ID = #{accountCost.userId} AND AC.TENANT_ID = #{accountCost.tenantId}
AND AC.ID = #{accountCost.id}
GROUP BY AC.ID
UNION ALL
SELECT AC.ID, AC.CREATE_TIME, AC.MODIFY_TIME, AC.LOGIC_DEL, AC.REC_VER, AC.TENANT_ID, AC.COST_DESC, AC.OUTLAY, AC.COST_TYPE, AC.PAYMENT_SIGN, AC.PAYMENT_TIME, AC.ICON, AC.REMARK, AC.USER_ID, (SELECT NICK_NAME FROM SYS_USER WHERE ID = AC.USER_ID) AS AC_NICK_NAME, GROUP_CONCAT(SU.ID) AS SU_ID, GROUP_CONCAT(SU.NICK_NAME) AS NICK_NAME FROM account_cost AC LEFT JOIN account_cost_user ACU ON AC.ID = ACU.COST_ID INNER JOIN sys_user SU ON ACU.USER_ID = SU.ID WHERE 1 = 1 AND AC.LOGIC_DEL = 0 AND AC.TENANT_ID = #{accountCost.tenantId} AND AC.USER_ID <> #{accountCost.userId}
AND ACU.COST_ID = #{accountCost.id}
GROUP BY AC.ID

SELECT T.COST_DESC, T.OUTLAY, T.COST_TYPE, T.PAYMENT_SIGN, T.PAYMENT_SIGN_NAME, T.PAYMENT_TIME, T.ICON, T.REMARK, T.CREATE_TIME, T.PAYMENT_TIME_GROUPING_KEY FROM (SELECT AC.COST_DESC, ROUND(IFNULL(AC.OUTLAY, 0) / CASE
WHEN (SELECT COUNT(1) FROM account_cost_user ACU WHERE 1 = 1 AND ACU.COST_ID = AC.ID) = 0 THEN 1 ELSE (SELECT COUNT(1) FROM account_cost_user ACU WHERE 1 = 1 AND ACU.COST_ID = AC.ID) END , 2) AS OUTLAY, AC.COST_TYPE, AC.PAYMENT_SIGN, SDV.VALUE_NAME AS PAYMENT_SIGN_NAME, AC.PAYMENT_TIME, AC.ICON, AC.REMARK, AC.CREATE_TIME, DATE_FORMAT(AC.PAYMENT_TIME, '%Y-%m-%d') AS PAYMENT_TIME_GROUPING_KEY FROM account_cost AC LEFT JOIN SYS_DICT_VALUE SDV ON SDV.DICT_KEY = 'PAYMENT_SIGN' WHERE 1 = 1 AND AC.LOGIC_DEL = 0 AND AC.TENANT_ID = #{accountCostDto.tenantId}
AND AC.TENANT_ID = #{accountCostDto.tenantId}
AND AC.USER_ID = #{accountCostDto.userId} AND AC.PAYMENT_TIME >= #{accountCostDto.paymentTimeFrom} AND AC.PAYMENT_TIME <= #{accountCostDto.paymentTimeTo} GROUP BY AC.ID
UNION ALL
SELECT AC.COST_DESC, ROUND(IFNULL(AC.OUTLAY, 0) / CASE
WHEN (SELECT COUNT(1) FROM account_cost_user ACU WHERE 1 = 1 AND ACU.COST_ID = AC.ID) = 0 THEN 1 ELSE (SELECT COUNT(1) FROM account_cost_user ACU WHERE 1 = 1 AND ACU.COST_ID = AC.ID) END , 2) AS OUTLAY, AC.COST_TYPE, AC.PAYMENT_SIGN, SDV.VALUE_NAME AS PAYMENT_SIGN_NAME, AC.PAYMENT_TIME, AC.ICON, AC.REMARK, AC.CREATE_TIME, DATE_FORMAT(AC.PAYMENT_TIME, '%Y-%m-%d') AS PAYMENT_TIME_GROUPING_KEY FROM account_cost AC LEFT JOIN account_cost_user ACU ON AC.ID = ACU.COST_ID LEFT JOIN SYS_DICT_VALUE SDV ON SDV.DICT_KEY = 'PAYMENT_SIGN' WHERE 1 = 1 AND AC.LOGIC_DEL = 0 AND AC.TENANT_ID = #{accountCostDto.tenantId}
AND AC.TENANT_ID = #{accountCostDto.tenantId}
AND ACU.USER_ID = #{accountCostDto.userId} AND AC.USER_ID <> #{accountCostDto.userId} AND AC.PAYMENT_TIME >= #{accountCostDto.paymentTimeFrom} AND AC.PAYMENT_TIME <= #{accountCostDto.paymentTimeTo} GROUP BY AC.ID) T GROUP BY T.PAYMENT_TIME, T.CREATE_TIME ORDER BY T.PAYMENT_TIME, T.CREATE_TIME

SELECT T.COST_TYPE, SUM(T.OUTLAY) AS OUTLAY FROM ( SELECT AC.COST_TYPE, ROUND( IFNULL( AC.OUTLAY, 0 ) / CASE
WHEN ( SELECT COUNT( 1 ) FROM account_cost_user ACU WHERE 1 = 1 AND ACU.COST_ID = AC.ID ) = 0 THEN 1 ELSE ( SELECT COUNT( 1 ) FROM account_cost_user ACU WHERE 1 = 1 AND ACU.COST_ID = AC.ID ) END, 2 ) AS OUTLAY FROM account_cost AC LEFT JOIN account_cost_user ACU ON AC.ID = ACU.COST_ID WHERE 1=1 AND AC.LOGIC_DEL = 0 AND AC.PAYMENT_SIGN = 'EXPENSES'
AND AC.TENANT_ID = #{accountCostDto.tenantId}
AND AC.USER_ID = #{accountCostDto.userId}
AND AC.PAYMENT_TIME >= #{accountCostDto.paymentTimeFrom} AND AC.PAYMENT_TIME <= #{accountCostDto.paymentTimeTo}
GROUP BY AC.ID
UNION ALL
SELECT AC.COST_TYPE, ROUND( IFNULL( AC.OUTLAY, 0 ) / CASE
WHEN ( SELECT COUNT( 1 ) FROM account_cost_user ACU WHERE 1 = 1 AND ACU.COST_ID = AC.ID ) = 0 THEN 1 ELSE ( SELECT COUNT( 1 ) FROM account_cost_user ACU WHERE 1 = 1 AND ACU.COST_ID = AC.ID ) END, 2 ) AS OUTLAY
FROM account_cost AC LEFT JOIN account_cost_user ACU ON AC.ID = ACU.COST_ID WHERE 1=1 AND AC.LOGIC_DEL = 0 AND AC.PAYMENT_SIGN = 'EXPENSES'
AND AC.TENANT_ID = #{accountCostDto.tenantId}
AND ACU.USER_ID = #{accountCostDto.userId} AND AC.USER_ID <> #{accountCostDto.userId}
AND AC.PAYMENT_TIME >= #{accountCostDto.paymentTimeFrom} AND AC.PAYMENT_TIME <= #{accountCostDto.paymentTimeTo}
GROUP BY AC.ID ) T GROUP BY T.COST_TYPE

WITH RECURSIVE dateseries AS (SELECT CURDATE() AS date UNION ALL SELECT DATE_SUB(date, INTERVAL 1 DAY) FROM dateseries WHERE DATE_SUB(date, INTERVAL 1 DAY) >= DATE_SUB(CURDATE(), INTERVAL 6 DAY)) SELECT ifnull(SUM(T.OUTLAY), 0) AS OUTLAY, ifnull(DATE_FORMAT(T.PAYMENT_TIME, '%Y-%m-%d'), DATE_FORMAT(DS.DATE, '%Y-%m-%d')) AS PAYMENT_TIME, IFNULL( CONCAT(STR_TO_DATE(T.PAYMENT_TIME, '%Y-%m-%d'), '(', SDV.VALUE_NAME, ')'), CONCAT(STR_TO_DATE(DS.DATE, '%Y-%m-%d'), '(', SDV.VALUE_NAME, ')') ) AS X_AXIS FROM DateSeries ds LEFT JOIN (SELECT ROUND(IFNULL(AC.OUTLAY, 0) / CASE
WHEN (SELECT COUNT(1) FROM account_cost_user ACU WHERE 1 = 1 AND ACU.COST_ID = AC.ID) = 0 THEN 1 ELSE (SELECT COUNT(1) FROM account_cost_user ACU WHERE 1 = 1 AND ACU.COST_ID = AC.ID) END , 2) AS OUTLAY, AC.PAYMENT_TIME FROM account_cost AC LEFT JOIN account_cost_user ACU ON AC.ID = ACU.COST_ID WHERE 1 = 1 AND AC.LOGIC_DEL = 0 AND AC.PAYMENT_SIGN = 'EXPENSES'
AND AC.TENANT_ID = #{accountCostDto.tenantId}
AND AC.USER_ID = #{accountCostDto.userId} AND AC.PAYMENT_TIME >= #{accountCostDto.paymentTimeFrom} AND AC.PAYMENT_TIME <= #{accountCostDto.paymentTimeTo}
AND AC.COST_TYPE = #{accountCostDto.costType}
GROUP BY AC.ID UNION ALL SELECT ROUND(IFNULL(AC.OUTLAY, 0) / CASE
WHEN (SELECT COUNT(1) FROM account_cost_user ACU WHERE 1 = 1 AND ACU.COST_ID = AC.ID) = 0 THEN 1 ELSE (SELECT COUNT(1) FROM account_cost_user ACU WHERE 1 = 1 AND ACU.COST_ID = AC.ID) END , 2) AS OUTLAY, AC.PAYMENT_TIME FROM account_cost AC LEFT JOIN account_cost_user ACU ON AC.ID = ACU.COST_ID WHERE 1 = 1 AND AC.LOGIC_DEL = 0 AND AC.PAYMENT_SIGN = 'EXPENSES'
AND AC.TENANT_ID = #{accountCostDto.tenantId}
AND ACU.USER_ID = #{accountCostDto.userId} AND AC.USER_ID <> #{accountCostDto.userId} AND AC.PAYMENT_TIME >= #{accountCostDto.paymentTimeFrom} AND AC.PAYMENT_TIME <= #{accountCostDto.paymentTimeTo}
AND AC.COST_TYPE = #{accountCostDto.costType}
GROUP BY AC.ID) T ON DATE_FORMAT(T.PAYMENT_TIME, '%Y-%m-%d') = ds.date LEFT JOIN sys_dict_value SDV ON SDV.DICT_KEY = 'WEEK_DAY' AND SDV.VALUE = WEEKDAY(STR_TO_DATE(IFNULL(T.PAYMENT_TIME, DS.DATE), '%Y-%m-%d')) + 1 GROUP BY ds.date ORDER BY DS.DATE

WITH RECURSIVE DATESERIES AS (SELECT CONCAT(#{accountCostDto.year}, '-', LPAD(#{accountCostDto.month}, 2, '0'), '-01') AS date UNION ALL SELECT DATE_ADD(date, INTERVAL 1 DAY) FROM DATESERIES WHERE DATE_ADD(date, INTERVAL 1 DAY) <= CASE WHEN #{accountCostDto.year} = YEAR(CURDATE()) AND #{accountCostDto.month} = MONTH(CURDATE()) THEN CURDATE() ELSE LAST_DAY(CONCAT(#{accountCostDto.year}, '-', LPAD(#{accountCostDto.month}, 2, '0'), '-01')) END) SELECT ifnull(SUM(T.OUTLAY), 0) AS OUTLAY, ifnull(DATE_FORMAT(T.PAYMENT_TIME, '%Y-%m-%d'), DATE_FORMAT(DS.DATE, '%Y-%m-%d')) AS PAYMENT_TIME, IFNULL( CONCAT(STR_TO_DATE(T.PAYMENT_TIME, '%Y-%m-%d'), '(', SDV.VALUE_NAME, ')'), CONCAT(STR_TO_DATE(DS.DATE, '%Y-%m-%d'), '(', SDV.VALUE_NAME, ')') ) AS X_AXIS FROM DateSeries ds LEFT JOIN (SELECT ROUND(IFNULL(AC.OUTLAY, 0) / CASE
WHEN (SELECT COUNT(1) FROM account_cost_user ACU WHERE 1 = 1 AND ACU.COST_ID = AC.ID) = 0 THEN 1 ELSE (SELECT COUNT(1) FROM account_cost_user ACU WHERE 1 = 1 AND ACU.COST_ID = AC.ID) END , 2) AS OUTLAY, AC.PAYMENT_TIME FROM account_cost AC LEFT JOIN account_cost_user ACU ON AC.ID = ACU.COST_ID WHERE 1 = 1 AND AC.LOGIC_DEL = 0 AND AC.PAYMENT_SIGN = 'EXPENSES'
AND AC.TENANT_ID = #{accountCostDto.tenantId}
AND AC.USER_ID = #{accountCostDto.userId}
AND AC.COST_TYPE = #{accountCostDto.costType}
AND YEAR(AC.PAYMENT_TIME) = #{accountCostDto.year} AND MONTH(AC.PAYMENT_TIME) = #{accountCostDto.month} GROUP BY AC.ID
UNION ALL
SELECT ROUND(IFNULL(AC.OUTLAY, 0) / CASE
WHEN (SELECT COUNT(1) FROM account_cost_user ACU WHERE 1 = 1 AND ACU.COST_ID = AC.ID) = 0 THEN 1 ELSE (SELECT COUNT(1) FROM account_cost_user ACU WHERE 1 = 1 AND ACU.COST_ID = AC.ID) END , 2) AS OUTLAY, AC.PAYMENT_TIME FROM account_cost AC LEFT JOIN account_cost_user ACU ON AC.ID = ACU.COST_ID WHERE 1 = 1 AND AC.LOGIC_DEL = 0 AND AC.PAYMENT_SIGN = 'EXPENSES'
AND AC.TENANT_ID = #{accountCostDto.tenantId}
AND ACU.USER_ID = #{accountCostDto.userId} AND AC.USER_ID <> #{accountCostDto.userId}
AND AC.COST_TYPE = #{accountCostDto.costType}
AND YEAR(AC.PAYMENT_TIME) = #{accountCostDto.year} AND MONTH(AC.PAYMENT_TIME) = #{accountCostDto.month} GROUP BY AC.ID) T ON DATE_FORMAT(T.PAYMENT_TIME, '%Y-%m-%d') = ds.date LEFT JOIN sys_dict_value SDV ON SDV.DICT_KEY = 'WEEK_DAY' AND SDV.VALUE = WEEKDAY(STR_TO_DATE(IFNULL(T.PAYMENT_TIME, DS.DATE), '%Y-%m-%d')) + 1 GROUP BY ds.date ORDER BY DS.DATE

WITH RECURSIVE DateSeries AS (SELECT CONCAT(#{accountCostDto.year}, '-01-01') AS date UNION ALL SELECT DATE_ADD(date, INTERVAL 1 DAY) FROM DateSeries WHERE DATE_ADD(date, INTERVAL 1 DAY) <= CASE WHEN #{accountCostDto.year} = YEAR(CURDATE()) THEN CURDATE() ELSE CONCAT(#{accountCostDto.year}, '-12-31') END) SELECT ifnull(SUM(T.OUTLAY), 0) AS OUTLAY, ifnull(DATE_FORMAT(T.PAYMENT_TIME, '%Y-%m-%d'), DATE_FORMAT(DS.DATE, '%Y-%m-%d')) AS PAYMENT_TIME, IFNULL( CONCAT(STR_TO_DATE(T.PAYMENT_TIME, '%Y-%m-%d'), '(', SDV.VALUE_NAME, ')'), CONCAT(STR_TO_DATE(DS.DATE, '%Y-%m-%d'), '(', SDV.VALUE_NAME, ')') ) AS X_AXIS FROM DateSeries ds LEFT JOIN (SELECT ROUND(IFNULL(AC.OUTLAY, 0) / CASE
WHEN (SELECT COUNT(1) FROM account_cost_user ACU WHERE 1 = 1 AND ACU.COST_ID = AC.ID) = 0 THEN 1 ELSE (SELECT COUNT(1) FROM account_cost_user ACU WHERE 1 = 1 AND ACU.COST_ID = AC.ID) END , 2) AS OUTLAY, AC.PAYMENT_TIME FROM account_cost AC LEFT JOIN account_cost_user ACU ON AC.ID = ACU.COST_ID WHERE 1 = 1 AND AC.LOGIC_DEL = 0 AND AC.PAYMENT_SIGN = 'EXPENSES'
AND AC.TENANT_ID = #{accountCostDto.tenantId}
AND AC.USER_ID = #{accountCostDto.userId}
AND AC.COST_TYPE = #{accountCostDto.costType}
AND YEAR(AC.PAYMENT_TIME) = #{accountCostDto.year} GROUP BY AC.ID
UNION ALL
SELECT ROUND(IFNULL(AC.OUTLAY, 0) / CASE
WHEN (SELECT COUNT(1) FROM account_cost_user ACU WHERE 1 = 1 AND ACU.COST_ID = AC.ID) = 0 THEN 1 ELSE (SELECT COUNT(1) FROM account_cost_user ACU WHERE 1 = 1 AND ACU.COST_ID = AC.ID) END , 2) AS OUTLAY, AC.PAYMENT_TIME FROM account_cost AC LEFT JOIN account_cost_user ACU ON AC.ID = ACU.COST_ID WHERE 1 = 1 AND AC.LOGIC_DEL = 0 AND AC.PAYMENT_SIGN = 'EXPENSES'
AND AC.TENANT_ID = #{accountCostDto.tenantId}
AND ACU.USER_ID = #{accountCostDto.userId} AND AC.USER_ID <> #{accountCostDto.userId}
AND AC.COST_TYPE = #{accountCostDto.costType}
AND YEAR(AC.PAYMENT_TIME) = #{accountCostDto.year} GROUP BY AC.ID) T ON DATE_FORMAT(T.PAYMENT_TIME, '%Y-%m-%d') = ds.date LEFT JOIN sys_dict_value SDV ON SDV.DICT_KEY = 'WEEK_DAY' AND SDV.VALUE = WEEKDAY(STR_TO_DATE(IFNULL(T.PAYMENT_TIME, DS.DATE), '%Y-%m-%d')) + 1 GROUP BY ds.date ORDER BY DS.DATE

SELECT DISTINCT AC.COST_TYPE
FROM account_cost AC
WHERE 1 = 1
AND AC.LOGIC_DEL = 0
AND AC.USER_ID = #{accountCostDto.userId}

    AND AC.PAYMENT_TIME >= #{accountCostDto.paymentTimeFrom}
    AND AC.PAYMENT_TIME <= #{accountCostDto.paymentTimeTo}


UNION

SELECT DISTINCT AC.COST_TYPE
FROM account_cost AC
LEFT JOIN account_cost_user ACU ON AC.ID = ACU.COST_ID
WHERE 1 = 1
AND AC.LOGIC_DEL = 0
AND AC.USER_ID <> #{accountCostDto.userId}
AND ACU.USER_ID = #{accountCostDto.userId}

    AND AC.PAYMENT_TIME >= #{accountCostDto.paymentTimeFrom}
    AND AC.PAYMENT_TIME <= #{accountCostDto.paymentTimeTo}
